using System.Text.Json;
using HanhTrangLop1.Models;
using Microsoft.EntityFrameworkCore;

namespace HanhTrangLop1.Data;

/// <summary>Visual-first curriculum. Voice is never generated by this seed.</summary>
public static class LearningContentSeed
{
    public const string CurrentPrefix = "curriculum-v3-";
    public static readonly string[] VietnameseAlphabet = ["A","Ă","Â","B","C","D","Đ","E","Ê","G","H","I","K","L","M","N","O","Ô","Ơ","P","Q","R","S","T","U","Ư","V","X","Y"];
    public static readonly string[] EnglishAlphabet = Enumerable.Range('A', 26).Select(x => ((char)x).ToString()).ToArray();
    public static readonly string[] CombinedAlphabet = ["A","Ă","Â","B","C","D","Đ","E","Ê","F","G","H","I","J","K","L","M","N","O","Ô","Ơ","P","Q","R","S","T","U","Ư","V","W","X","Y","Z"];

    public static async Task<bool> RequiresCurriculumResetAsync(ApplicationDbContext db) =>
        await db.LearningItems.AnyAsync() && !await db.LearningItems.AnyAsync(x => x.Code.StartsWith(CurrentPrefix));

    public static async Task<(int Lessons, int Attempts, int Sessions, int Children)> ResetLearningDataAsync(ApplicationDbContext db)
    {
        await using var transaction = await db.Database.BeginTransactionAsync();
        var result = (await db.LearningItems.CountAsync(), await db.LearningAttempts.CountAsync(), await db.LearningSessions.CountAsync(), await db.ChildProfiles.CountAsync());
        await db.QuestionAttempts.ExecuteDeleteAsync(); await db.LearningAttempts.ExecuteDeleteAsync(); await db.LearningSessions.ExecuteDeleteAsync();
        await db.SkillProgress.ExecuteDeleteAsync(); await db.ChildRewards.ExecuteDeleteAsync(); await db.GardenItems.ExecuteDeleteAsync();
        await db.ChildProfiles.ExecuteDeleteAsync(); await db.ContentReviews.ExecuteDeleteAsync(); await db.Questions.ExecuteDeleteAsync();
        await db.LearningItems.ExecuteDeleteAsync(); await db.TracingTemplates.ExecuteDeleteAsync();
        await transaction.CommitAsync(); return result;
    }

    public static async Task<int> SeedAsync(ApplicationDbContext db)
    {
        var groups = await db.SkillGroups.AsNoTracking().ToDictionaryAsync(x => x.Code, StringComparer.OrdinalIgnoreCase);
        var definitions = BuildDefinitions(); ValidateDefinitions(definitions, groups.Keys);
        var existing = await db.LearningItems.Include(x => x.Questions).Where(x => x.Code.StartsWith(CurrentPrefix)).ToDictionaryAsync(x => x.Code);
        var validCodes = definitions.Select(x => x.Code).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var obsolete = existing.Values.Where(x => !validCodes.Contains(x.Code)).ToList();
        if (obsolete.Count > 0)
        {
            var ids = obsolete.Select(x => x.Id).ToArray();
            var attempted = (await db.LearningAttempts.Where(x => ids.Contains(x.LearningItemId)).Select(x => x.LearningItemId).Distinct().ToListAsync()).ToHashSet();
            db.LearningItems.RemoveRange(obsolete.Where(x => !attempted.Contains(x.Id)));
            foreach (var item in obsolete.Where(x => attempted.Contains(x.Id))) item.Status = ContentStatus.Archived;
        }
        var created = 0; var now = DateTimeOffset.UtcNow;
        foreach (var d in definitions)
        {
            if (!groups.TryGetValue(d.GroupCode, out var group)) continue;
            if (!existing.TryGetValue(d.Code, out var item)) { item = new LearningItem { Id = Guid.NewGuid(), Code = d.Code, CreatedAt = now, Questions = [] }; db.LearningItems.Add(item); created++; }
            item.Title = d.Title; item.SkillGroupId = group.Id; item.TopicId = null; item.Level = d.Level; item.SortOrder = d.SortOrder;
            item.InteractionType = d.Type; item.EstimatedMinutes = d.Type == InteractionTypes.StoryChoice ? 6 : 4; item.InstructionText = d.Instruction;
            item.ContentJson = d.PayloadJson; item.Status = ContentStatus.Published; item.PublishedAt ??= now; item.UpdatedAt = now;
            var q = item.Questions.OrderBy(x => x.SortOrder).FirstOrDefault();
            if (q is null) { q = new Question { Id = Guid.NewGuid(), LearningItemId = item.Id, SortOrder = 1 }; item.Questions.Add(q); }
            q.PromptText = d.Prompt; q.QuestionType = d.Type; q.PayloadJson = d.PayloadJson;
            q.CorrectAnswerJson = d.Type == InteractionTypes.Tracing ? JsonSerializer.Serialize(new { minPoints = 20, expectedStrokeCount = d.Strokes }) : JsonSerializer.Serialize(new { value = d.Answer });
            q.HintJson = JsonSerializer.Serialize(new { level1 = d.Hint }); q.FeedbackJson = JsonSerializer.Serialize(new { correct = "Giỏi lắm, con làm đúng rồi!", retry = "Con nhìn kỹ rồi thử lại nhé." });
            if (d.Type == InteractionTypes.Tracing)
            {
                var id = JsonSerializer.Deserialize<JsonElement>(d.PayloadJson).GetProperty("templateId").GetGuid();
                if (!await db.TracingTemplates.AnyAsync(x => x.Id == id)) db.TracingTemplates.Add(new TracingTemplate { Id = id, SymbolType = d.GroupCode == "chu-so" ? "number" : d.GroupCode == "van-dong-tinh" ? "stroke" : "letter", Symbol = d.Symbol, DisplayName = d.Title, GuideJson = JsonSerializer.Serialize(new { guideMode = "outline", expectedStrokeCount = d.Strokes, showStartPoint = true }), CreatedAt = now });
            }
        }
        await SeedReferencedImagesAsync(db, definitions);
        var removedItemIds = obsolete.Select(x => x.Id).ToArray();
        var referencedPayloads = await db.Questions
            .Where(x => x.QuestionType == InteractionTypes.Tracing && !removedItemIds.Contains(x.LearningItemId))
            .Select(x => x.PayloadJson).ToListAsync();
        referencedPayloads.AddRange(definitions.Where(x => x.Type == InteractionTypes.Tracing).Select(x => x.PayloadJson));
        var referencedTemplateIds = referencedPayloads.Select(ReadTemplateId).Where(x => x.HasValue).Select(x => x!.Value).ToHashSet();
        var orphanTemplates = await db.TracingTemplates.Where(x => !referencedTemplateIds.Contains(x.Id)).ToListAsync();
        db.TracingTemplates.RemoveRange(orphanTemplates);
        await db.SaveChangesAsync(); return created;
    }

    private static List<LessonDefinition> BuildDefinitions()
    {
        var result = new List<LessonDefinition>(); var orders = new Dictionary<string,int>();
        void Add(LessonDefinition x) { orders.TryGetValue(x.GroupCode, out var n); n += 10; orders[x.GroupCode] = n; result.Add(x with { SortOrder = n }); }
        AddAlphabet();
        void AddAlphabet()
        {
            for (var i = 0; i < CombinedAlphabet.Length; i++)
            {
                var x = CombinedAlphabet[i]; var prev = CombinedAlphabet[(i + CombinedAlphabet.Length - 1) % CombinedAlphabet.Length]; var next = CombinedAlphabet[(i + 1) % CombinedAlphabet.Length];
                var inVietnamese = VietnameseAlphabet.Contains(x); var inEnglish = EnglishAlphabet.Contains(x);
                var language = inVietnamese && inEnglish ? "Tiếng Việt và tiếng Anh" : inVietnamese ? "Tiếng Việt" : "Tiếng Anh";
                var lower = x.ToLower(new System.Globalization.CultureInfo("vi-VN"));
                var prevLower = prev.ToLower(new System.Globalization.CultureInfo("vi-VN")); var nextLower = next.ToLower(new System.Globalization.CultureInfo("vi-VN"));
                Add(Choice($"letter-combined-single-upper-{i:00}", "chu-cai", InteractionTypes.SingleChoice, $"{language}: chọn chữ hoa {x}", $"Con hãy chọn chữ hoa {x}.", [prev,x,next], x, LetterImage(x)));
                Add(Choice($"letter-combined-single-lower-{i:00}", "chu-cai", InteractionTypes.SingleChoice, $"{language}: chọn chữ thường {lower}", $"Con hãy chọn chữ thường {lower}.", [prevLower,lower,nextLower], lower));
                Add(Choice($"letter-combined-multi-{i:00}", "chu-cai", InteractionTypes.MultiSelect, $"{language}: tìm hai dạng chữ {x}", $"Chọn chữ {x} viết hoa và viết thường.", [x,lower,prev,next.ToLower(new System.Globalization.CultureInfo("vi-VN"))], Canonical([x,lower])));
                Add(Choice($"letter-combined-listen-upper-{i:00}", "chu-cai", InteractionTypes.ListenAndChoose, $"{language}: nghe và chọn chữ hoa {x}", $"Nghe và chọn chữ hoa {x}.", [next,x,prev], x));
                Add(Choice($"letter-combined-listen-lower-{i:00}", "chu-cai", InteractionTypes.ListenAndChoose, $"{language}: nghe và chọn chữ thường {lower}", $"Nghe và chọn chữ thường {lower}.", [nextLower,lower,prevLower], lower));
                Add(Tracing($"letter-combined-trace-upper-{i:00}", "chu-cai", $"{language}: tô chữ hoa {x}", x, 2));
                Add(Tracing($"letter-combined-trace-lower-{i:00}", "chu-cai", $"{language}: tô chữ thường {lower}", lower, 2));
                Add(Matching($"letter-combined-match-{i:00}", "chu-cai", $"{language}: nối chữ hoa và thường {x}", [(x,lower),(prev,prevLower),(next,nextLower)]));
            }
        }
        for (var n = 0; n <= 20; n++)
        {
            var options = NumberChoices(n);
            Add(Choice($"number-single-{n:00}", "chu-so", InteractionTypes.SingleChoice, $"Chọn số {n}", $"Con hãy chọn số {n}.", options, n.ToString(), NumberImage(n)));
            Add(Choice($"number-listen-{n:00}", "chu-so", InteractionTypes.ListenAndChoose, $"Nghe và chọn số {n}", $"Nghe và chọn số {n}.", options.Reverse().ToArray(), n.ToString()));
            Add(Tracing($"number-trace-{n:00}", "chu-so", $"Tô số {n}", n.ToString(), n > 9 ? 2 : 1));
        }
        var symbols = new[] { "🍎","⭐","🐟","🌼","🦋","🚗","🍓","🐤","🎈" };
        for (var n = 1; n <= 9; n++)
        {
            var start = Math.Min(n, 7); var nums = Enumerable.Range(start, 3).ToArray();
            Add(Matching($"number-quantity-{n}", "chu-so", $"Nối số với lượng đồ vật {n}", nums.Select(x => (x.ToString(), Repeat(symbols[n-1], x))).ToArray()));
        }
        for (var n = 1; n <= 7; n++) { var seq = Enumerable.Range(n,3).Select(x => x.ToString()).ToArray(); Add(Ordering($"number-up-{n}", "chu-so", $"Từ bé đến lớn {n}–{n+2}", "Xếp ba số từ bé đến lớn.", seq)); Add(Ordering($"number-down-{n}", "chu-so", $"Từ lớn đến bé {n+2}–{n}", "Xếp ba số từ lớn đến bé.", seq.Reverse().ToArray())); }

        var artTracingTemplates = new[]
        {
            ("phong-canh", "Phong cảnh thiên nhiên"), ("do-dung", "Đồ dùng học tập"),
            ("hinh-hoc", "Hình học kỳ diệu"), ("meo-con", "Chú mèo con"),
            ("ca-heo", "Cá heo tung tăng"), ("o-che-mua", "Chiếc ô che mưa"),
            ("trai-tao", "Quả táo và chú sâu"), ("tau-hoa", "Đoàn tàu tí hon"),
            ("chu-tho", "Chú thỏ và cà rốt"), ("ong-vang", "Ong vàng và hoa"),
            ("may-bay", "Máy bay trên trời"), ("thuyen", "Thuyền buồm lướt sóng"),
            ("cau-vong", "Cầu vồng và lâu đài"), ("chu-buom", "Bướm xinh trong vườn"),
            ("khung-long", "Khủng long tí hon"), ("ten-lua", "Tên lửa và các vì sao")
        };
        foreach (var art in artTracingTemplates)
        {
            Add(Tracing($"picture-{art.Item1}", "van-dong-tinh", $"Tô tranh: {art.Item2}", art.Item1, 6));
        }

        for (var n = 1; n <= 9; n++) { Add(Counting($"math-count-{n}", "so-luong-toan", $"Đếm {n} đồ vật", symbols[n-1], n)); Add(Quantity($"math-make-{n}", "so-luong-toan", $"Tạo đúng {n} đồ vật", symbols[n-1], n)); }
        var objects = new[] { ("🍎","quả táo"),("⭐","ngôi sao"),("🐟","con cá"),("🌼","bông hoa") };
        for (var total = 2; total <= 9; total++) { var o = objects[total % 4]; Add(Equation($"math-add-single-{total}", InteractionTypes.SingleChoice, $"Phép cộng bằng {total}", total-1, 1, "+", o.Item1, o.Item2)); Add(Equation($"math-add-drag-{total}", InteractionTypes.DragDrop, $"Kéo kết quả phép cộng {total}", total-1, 1, "+", o.Item1, o.Item2)); Add(Equation($"math-sub-single-{total}", InteractionTypes.SingleChoice, $"Phép trừ từ {total}", total, 1, "−", o.Item1, o.Item2)); Add(Equation($"math-sub-drag-{total}", InteractionTypes.DragDrop, $"Kéo kết quả phép trừ {total}", total, 1, "−", o.Item1, o.Item2)); }
        foreach (var x in new[] { (2,5,"more"),(7,3,"more"),(4,4,"equal"),(6,6,"equal"),(2,8,"less"),(5,9,"less") }) Add(Comparison($"math-compare-{x.Item3}-{x.Item1}-{x.Item2}", "so-luong-toan", $"{(x.Item3 == "equal" ? "Chọn hai nhóm bằng nhau" : x.Item3 == "less" ? "Chọn nhóm ít hơn" : "Chọn nhóm nhiều hơn")}: {x.Item1} và {x.Item2}", "●", $"Nhóm {x.Item1}", x.Item1, $"Nhóm {x.Item2}", x.Item2, x.Item3));

        AddVisualGroup("tu-duy-logic", "logic", true);
        AddVisualGroup("ky-nang-song", "life", false);
        AddVisualGroup("ngon-ngu", "language", false);
        AddVisualGroup("ghi-nho-tap-trung", "memory", true);
        AddExtraVisualLessons("tu-duy-logic", "logic"); AddExtraVisualLessons("ky-nang-song", "life"); AddExtraVisualLessons("ngon-ngu", "language"); AddExtraVisualLessons("ghi-nho-tap-trung", "memory");
        void AddVisualGroup(string group, string prefix, bool logic)
        {
            Add(Choice($"{prefix}-single-animal", group, InteractionTypes.SingleChoice, "Tìm hình phù hợp", "Vật nào là con vật?", ["Con mèo","Quả táo","Bút chì"], "Con mèo"));
            Add(Choice($"{prefix}-single-food", group, InteractionTypes.SingleChoice, "Tìm thức ăn", "Vật nào ăn được?", ["Cà rốt","Cái cốc","Quyển sách"], "Cà rốt"));
            Add(Choice($"{prefix}-multi-animals", group, InteractionTypes.MultiSelect, "Chọn các con vật", "Chọn tất cả con vật.", ["Con mèo","Con cá","Quả táo","Bút chì"], "Con cá|Con mèo"));
            Add(Choice($"{prefix}-multi-school", group, InteractionTypes.MultiSelect, "Chọn đồ dùng học tập", "Chọn tất cả đồ dùng học tập.", ["Bút chì","Quyển sách","Con thỏ","Quả cam"], "Bút chì|Quyển sách"));
            Add(Matching($"{prefix}-match-food", group, "Nối con vật với thức ăn", [("Con thỏ","Cà rốt"),("Con mèo","Con cá"),("Con ong","Bông hoa")]));
            Add(Matching($"{prefix}-match-use", group, "Nối đồ vật với công dụng", [("Cái cốc","Uống nước"),("Cái ô","Che mưa"),("Bút chì","Vẽ tranh")]));
            Add(Ordering($"{prefix}-order-morning", group, "Trình tự buổi sáng", "Xếp đúng ba bước.", ["Thức dậy","Đánh răng","Ăn sáng"]));
            Add(Ordering($"{prefix}-order-plant", group, "Cây lớn lên", "Xếp đúng ba giai đoạn.", ["Hạt giống","Mầm cây","Cây non"]));
            Add(Classification($"{prefix}-sort-food", group, "Phân loại thức ăn", ["Trái cây","Rau củ"], [("Quả táo","Trái cây"),("Quả cam","Trái cây"),("Cà rốt","Rau củ"),("Bắp cải","Rau củ")]));
            Add(Classification($"{prefix}-sort-living", group, "Phân loại hình ảnh", ["Con vật","Đồ vật"], [("Con mèo","Con vật"),("Con cá","Con vật"),("Bút chì","Đồ vật"),("Cái cốc","Đồ vật")]));
            if (group == "ngon-ngu" || group == "ghi-nho-tap-trung") { Add(Choice($"{prefix}-listen-cat", group, InteractionTypes.ListenAndChoose, "Nghe từ con mèo", "Nghe và chọn con mèo.", ["Con chó","Con mèo","Con vịt"], "Con mèo")); Add(Choice($"{prefix}-listen-apple", group, InteractionTypes.ListenAndChoose, "Nghe từ quả táo", "Nghe và chọn quả táo.", ["Quả táo","Quả cam","Cà rốt"], "Quả táo")); }
            if (!logic) AddStories(group, group == "ky-nang-song" ? Stories.Take(6) : Stories.Skip(6));
        }
        void AddExtraVisualLessons(string group, string prefix)
        {
            Add(Choice($"{prefix}-single-weather", group, InteractionTypes.SingleChoice, "Chọn hình theo thời tiết", "Trời mưa cần vật nào?", ["Cái ô","Kính râm","Quạt giấy"], "Cái ô"));
            Add(Choice($"{prefix}-single-action", group, InteractionTypes.SingleChoice, "Chọn hành động phù hợp", "Muốn vẽ tranh con chọn gì?", ["Bút chì","Cái thìa","Đôi dép"], "Bút chì"));
            Add(Choice($"{prefix}-single-home", group, InteractionTypes.SingleChoice, "Tìm nơi ở phù hợp", "Con cá sống ở đâu?", ["Dưới nước","Trên cây","Trong cặp"], "Dưới nước"));
            Add(Choice($"{prefix}-multi-fruit", group, InteractionTypes.MultiSelect, "Chọn các loại quả", "Chọn tất cả các loại quả.", ["Quả táo","Quả cam","Cà rốt","Bút chì"], "Quả cam|Quả táo"));
            Add(Choice($"{prefix}-multi-safe", group, InteractionTypes.MultiSelect, "Chọn việc an toàn", "Chọn các việc an toàn.", ["Nắm tay người lớn","Cài dây an toàn","Chạm ổ điện","Chơi gần bếp nóng"], "Cài dây an toàn|Nắm tay người lớn"));
            Add(Choice($"{prefix}-multi-water", group, InteractionTypes.MultiSelect, "Chọn con vật dưới nước", "Chọn các con vật sống dưới nước.", ["Con cá","Con tôm","Con mèo","Con thỏ"], "Con cá|Con tôm"));
            Add(Matching($"{prefix}-match-home", group, "Nối con vật với nơi sống", [("Con cá","Dưới nước"),("Con chim","Tổ chim"),("Con chó","Ngôi nhà")]));
            Add(Matching($"{prefix}-match-weather", group, "Nối thời tiết với đồ dùng", [("Trời mưa","Cái ô"),("Trời nắng","Mũ rộng vành"),("Trời lạnh","Áo ấm")]));
            Add(Matching($"{prefix}-match-shape", group, "Nối đồ vật với hình dạng", [("Quả bóng","Hình tròn"),("Cái hộp","Hình vuông"),("Mái nhà","Hình tam giác")]));
            Add(Ordering($"{prefix}-order-hands", group, "Ba bước rửa tay", "Xếp đúng ba bước.", ["Làm ướt tay","Xoa xà phòng","Rửa sạch"]));
            Add(Ordering($"{prefix}-order-story", group, "Trình tự câu chuyện ngắn", "Xếp việc xảy ra trước đến sau.", ["Gieo hạt","Tưới nước","Cây nảy mầm"]));
            Add(Ordering($"{prefix}-order-school", group, "Ba bước vào lớp", "Xếp đúng ba bước.", ["Chào cô","Cất ba lô","Ngồi vào chỗ"]));
            Add(Classification($"{prefix}-sort-habitat", group, "Phân loại nơi sống", ["Trên cạn","Dưới nước"], [("Con mèo","Trên cạn"),("Con thỏ","Trên cạn"),("Con cá","Dưới nước"),("Con tôm","Dưới nước")]));
            Add(Classification($"{prefix}-sort-weather", group, "Phân loại đồ dùng thời tiết", ["Ngày mưa","Ngày nắng"], [("Cái ô","Ngày mưa"),("Áo mưa","Ngày mưa"),("Kính râm","Ngày nắng"),("Mũ rộng vành","Ngày nắng")]));
            Add(Classification($"{prefix}-sort-shape", group, "Phân loại hình", ["Có góc","Không có góc"], [("Hình vuông","Có góc"),("Hình tam giác","Có góc"),("Hình tròn","Không có góc"),("Hình bầu dục","Không có góc")]));
        }

        foreach (var shape in new[] { ("circle","Hình tròn"),("square","Hình vuông"),("triangle","Hình tam giác"),("rectangle","Hình chữ nhật") }) Add(Choice($"shape-single-{shape.Item1}", "hinh-dang-khong-gian", InteractionTypes.SingleChoice, $"Nhận biết {shape.Item2}", $"Đâu là {shape.Item2}?", ["Hình tròn","Hình vuông","Hình tam giác","Hình chữ nhật"], shape.Item2));
        Add(Matching("shape-match", "hinh-dang-khong-gian", "Nối hình với tên", [("●","Hình tròn"),("■","Hình vuông"),("▲","Hình tam giác")]));
        Add(Matching("shape-match-object", "hinh-dang-khong-gian", "Nối đồ vật với hình dạng", [("Quả bóng","Hình tròn"),("Cái hộp","Hình vuông"),("Mái nhà","Hình tam giác")]));
        Add(Matching("shape-match-same", "hinh-dang-khong-gian", "Nối hai hình giống nhau", [("Tròn đỏ","Hình tròn"),("Vuông xanh","Hình vuông"),("Tam giác vàng","Hình tam giác")]));
        Add(Classification("shape-sort-corners", "hinh-dang-khong-gian", "Phân loại theo góc", ["Có góc","Không có góc"], [("Hình vuông","Có góc"),("Hình tam giác","Có góc"),("Hình tròn","Không có góc"),("Hình bầu dục","Không có góc")]));
        Add(Classification("shape-sort-round", "hinh-dang-khong-gian", "Phân loại hình tròn", ["Dạng tròn","Không tròn"], [("Hình tròn","Dạng tròn"),("Hình bầu dục","Dạng tròn"),("Hình vuông","Không tròn"),("Hình tam giác","Không tròn")]));
        Add(Classification("shape-sort-size", "hinh-dang-khong-gian", "Phân loại kích thước", ["Hình lớn","Hình nhỏ"], [("Tròn lớn","Hình lớn"),("Vuông lớn","Hình lớn"),("Tròn nhỏ","Hình nhỏ"),("Vuông nhỏ","Hình nhỏ")]));
        Add(Choice("shape-drag-above", "hinh-dang-khong-gian", InteractionTypes.DragDrop, "Vị trí phía trên", "Kéo quả bóng vào phía trên.", ["Quả bóng","Quyển sách","Cái cốc"], "Quả bóng"));
        Add(Choice("shape-drag-inside", "hinh-dang-khong-gian", InteractionTypes.DragDrop, "Vị trí bên trong", "Kéo con mèo vào trong ngôi nhà.", ["Con mèo","Con cá","Con chim"], "Con mèo"));
