        void AddStories(string group, IEnumerable<StorySpec> stories) { foreach (var s in stories) Add(Story($"{group}-story-{s.Slug}", group, s.Title, s.Speech, s.Prompt, s.Choices, s.Answer, $"/images/lessons/doc-hieu/ill-{s.Slug}.jpg")); }
        void EnsureExtendedCoverage()
        {
            var extendedGroups = new[] { "tu-duy-logic", "ky-nang-song", "ngon-ngu", "hinh-dang-khong-gian", "ghi-nho-tap-trung", "van-dong-tinh", "kham-pha" };
            foreach (var group in extendedGroups)
            {
                var profile = CoverageProfiles[group];
                var rule = ActivityTemplateCatalog.ForSkillGroup(group);
                var types = rule.InteractionTypes.Concat(rule.AllowsTracing ? [InteractionTypes.Tracing] : []);
                foreach (var type in types)
                {
                    var current = result.Count(x => x.GroupCode == group && x.Type == type);
                    for (var index = current; index < 16; index++) Add(CreateCoverageLesson(profile, type, index));
                }
            }
        }
    }

    private static LessonDefinition CreateCoverageLesson(CoverageProfile profile, string type, int index)
    {
        string Item(int offset) => profile.Items[(index + offset) % profile.Items.Length];
        (string Left, string Right) Pair(int offset) => profile.Pairs[(index + offset) % profile.Pairs.Length];
        var typeName = ActivityTemplateCatalog.GetDisplayName(type);
        var slug = $"coverage-{profile.Code}-{type}-{index:00}";
        var title = $"{typeName}: {profile.Theme} {index + 1:00}";
        return type switch
        {
            InteractionTypes.SingleChoice => Choice(slug, profile.GroupCode, type, title, $"Con hãy chọn {Item(0)}.", [Item(1),Item(0),Item(2)], Item(0)),
            InteractionTypes.ListenAndChoose => Choice(slug, profile.GroupCode, type, title, $"Nghe và chọn {Item(0)}.", [Item(2),Item(0),Item(1)], Item(0)),
            InteractionTypes.DragDrop => Choice(slug, profile.GroupCode, type, title, $"Kéo {Pair(0).Left} tới {Pair(0).Right}.", [Pair(0).Left,Item(1),Item(2)], Pair(0).Left, "", new { targetLabel=Pair(0).Right }),
            InteractionTypes.MultiSelect => Choice(slug, profile.GroupCode, type, title, $"Chọn {Item(0)} và {Item(1)}.", [Item(0),Item(2),Item(1),Item(3)], Canonical([Item(0),Item(1)])),
            InteractionTypes.Matching => Matching(slug, profile.GroupCode, title, [Pair(0),Pair(1),Pair(2)]),
            InteractionTypes.Ordering => Ordering(slug, profile.GroupCode, title, "Quan sát mẫu rồi xếp lại ba hình theo đúng thứ tự.", [Item(0),Item(1),Item(2)]),
            InteractionTypes.Classification => Classification(slug, profile.GroupCode, title, [profile.CategoryA,profile.CategoryB],
                [(profile.CategoryAItems[index%profile.CategoryAItems.Length],profile.CategoryA),(profile.CategoryAItems[(index+1)%profile.CategoryAItems.Length],profile.CategoryA),(profile.CategoryBItems[index%profile.CategoryBItems.Length],profile.CategoryB),(profile.CategoryBItems[(index+1)%profile.CategoryBItems.Length],profile.CategoryB)]),
            InteractionTypes.StoryChoice => Story(slug, profile.GroupCode, title,
                $"Trong câu chuyện nhỏ, bạn An nhìn thấy {Pair(0).Left}. An nhớ rằng {Pair(0).Left} đi cùng với {Pair(0).Right}. An quan sát thật kỹ rồi vui vẻ hoàn thành hoạt động.",
                $"An nhìn thấy gì?", [Pair(0).Left,Item(1),Item(2)], Pair(0).Left, ImageForLabel(Pair(0).Left)),
            InteractionTypes.Comparison => ShapeComparison(slug, title, new[]{"●","■","▲"}[index%3], new[]{"Hình tròn","Hình vuông","Hình tam giác"}[index%3], 62+(index%4)*18, 126-(index%3)*12, index%2==0?"more":"less"),
            InteractionTypes.Tracing => Tracing(slug, profile.GroupCode, title, new[]{"|","—","/","\\","C","S","O","U","∩","∪","Z","M","W","△","□","○"}[index%16], 1),
            _ => throw new InvalidOperationException($"Không thể tạo bài phủ cho dạng {type}.")
        };
    }

