    private static object Merge(object basis, object? extra) { var o=JsonSerializer.SerializeToNode(basis)!.AsObject(); if(extra is not null) foreach(var p in JsonSerializer.SerializeToNode(extra)!.AsObject()) o[p.Key]=p.Value?.DeepClone(); return o; }
    private static string[] NumberChoices(int n) => new[]{Math.Max(0,n-1).ToString(),n.ToString(),Math.Min(20,n+1).ToString()}.Distinct().ToArray();
    private static string Repeat(string x,int n)=>string.Join(' ',Enumerable.Repeat(x,n)); private static string Canonical(IEnumerable<string> x)=>string.Join('|',x.Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(v=>v,StringComparer.OrdinalIgnoreCase)); private static string CanonicalMappings(IEnumerable<(string Left,string Right)> x)=>string.Join('|',x.OrderBy(v=>v.Left,StringComparer.OrdinalIgnoreCase).Select(v=>$"{v.Left}=>{v.Right}"));
    private static string LetterImage(string x) { var lower=x.ToLower(new System.Globalization.CultureInfo("vi-VN")); return $"/images/photos/flashcard-letter-{lower}.{("ăâđêôơư".Contains(lower)?"svg":"jpg")}"; } private static string NumberImage(int n)=>n==0?"/images/photos/flashcard-number-0.svg":$"/images/photos/flashcard-number-{n}.jpg";
    public static string ResolveLetterFlashcardUrl(string symbol)=>LegacyLearningContentSeed.ResolveLetterFlashcardUrl(symbol); public static string ResolveTracingFlashcardUrl(string symbol)=>LegacyLearningContentSeed.ResolveTracingFlashcardUrl(symbol); private static Guid StableGuid(string value)=>new(System.Security.Cryptography.MD5.HashData(System.Text.Encoding.UTF8.GetBytes(value)));

    private static void ValidateDefinitions(IReadOnlyCollection<LessonDefinition> ds,IEnumerable<string> groups)
    {
        var duplicateCodes=ds.GroupBy(x=>x.Code).Where(x=>x.Count()>1).Select(x=>x.Key).ToArray(); var duplicateTitles=ds.GroupBy(x=>$"{x.GroupCode}|{x.Title}",StringComparer.OrdinalIgnoreCase).Where(x=>x.Count()>1).Select(x=>x.Key).ToArray();
        if(duplicateCodes.Length>0||duplicateTitles.Length>0) throw new InvalidOperationException($"Kho bài học có mã hoặc tên bị lặp. Mã: {string.Join(",",duplicateCodes)}; tên: {string.Join(",",duplicateTitles)}");
        foreach(var group in groups) { var list=ds.Where(x=>x.GroupCode.Equals(group,StringComparison.OrdinalIgnoreCase)).ToList(); if(list.Count<5) throw new InvalidOperationException($"Nhóm {group} chưa đủ bài."); var rule=ActivityTemplateCatalog.ForSkillGroup(group); var missing=rule.InteractionTypes.Concat(rule.AllowsTracing?[InteractionTypes.Tracing]:[]).Where(t=>list.All(x=>x.Type!=t)); if(missing.Any()) throw new InvalidOperationException($"Nhóm {group} thiếu dạng: {string.Join(", ",missing)}"); }
        var extendedGroups=new[]{"tu-duy-logic","ky-nang-song","ngon-ngu","hinh-dang-khong-gian","ghi-nho-tap-trung","van-dong-tinh","kham-pha"};
        foreach(var group in extendedGroups) { var rule=ActivityTemplateCatalog.ForSkillGroup(group); foreach(var type in rule.InteractionTypes.Concat(rule.AllowsTracing?[InteractionTypes.Tracing]:[])) { var count=ds.Count(x=>x.GroupCode==group&&x.Type==type); if(count<16) throw new InvalidOperationException($"Nhóm {group}, dạng {type} chỉ có {count} bài; yêu cầu tối thiểu 16 bài."); } }
        var expected=CombinedAlphabet.Length;
        foreach(var type in new[]{InteractionTypes.MultiSelect,InteractionTypes.Matching}) if(ds.Count(x=>x.GroupCode=="chu-cai"&&x.Type==type)!=expected) throw new InvalidOperationException($"Dạng {type} phải đủ {expected} bài chữ đã gộp Việt–Anh.");
        foreach(var type in new[]{InteractionTypes.SingleChoice,InteractionTypes.ListenAndChoose,InteractionTypes.Tracing}) if(ds.Count(x=>x.GroupCode=="chu-cai"&&x.Type==type)!=expected*2) throw new InvalidOperationException($"Dạng {type} phải đủ {expected} chữ hoa và {expected} chữ thường.");
        if(ds.Count(x=>x.GroupCode=="van-dong-tinh"&&x.Type==InteractionTypes.Tracing&&x.Code.Contains("picture-",StringComparison.OrdinalIgnoreCase))<16) throw new InvalidOperationException("Tô tranh & Tạo hình nghệ thuật phải có ít nhất 16 tranh.");
    }
    private static async Task SeedReferencedImagesAsync(ApplicationDbContext db,IEnumerable<LessonDefinition> ds)
    {
        var paths=ds.SelectMany(x=>ExtractImagePaths(x.PayloadJson)).Distinct(StringComparer.OrdinalIgnoreCase).ToList(); var existing=(await db.MediaAssets.Where(x=>x.AssetType=="image").Select(x=>x.StoragePath).ToListAsync()).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach(var path in paths.Where(x=>!existing.Contains(x))) db.MediaAssets.Add(new MediaAsset{Id=Guid.NewGuid(),AssetType="image",FileName=Path.GetFileName(path),ContentType=Path.GetExtension(path).Equals(".svg",StringComparison.OrdinalIgnoreCase)?"image/svg+xml":"image/jpeg",StoragePath=path,AltText="Hình minh họa bài học",CreatedAt=DateTimeOffset.UtcNow});
    }
    private static IEnumerable<string> ExtractImagePaths(string json) { using var doc=JsonDocument.Parse(json); return Walk(doc.RootElement).ToArray(); static IEnumerable<string> Walk(JsonElement e) { if(e.ValueKind==JsonValueKind.Object) foreach(var p in e.EnumerateObject()) foreach(var x in Walk(p.Value)) yield return x; else if(e.ValueKind==JsonValueKind.Array) foreach(var c in e.EnumerateArray()) foreach(var x in Walk(c)) yield return x; else if(e.ValueKind==JsonValueKind.String&&e.GetString() is {Length:>0} s&&s.StartsWith("/images/")) yield return s; } }
    private static Guid? ReadTemplateId(string json) { try { using var doc=JsonDocument.Parse(json); return doc.RootElement.TryGetProperty("templateId",out var value)&&value.TryGetGuid(out var id)?id:null; } catch(JsonException) { return null; } }
