    private static string ImageForLabel(string label)
    {
        var value=label.ToLowerInvariant();
        var file=value.Contains("mèo")?"cat":value.Contains("chó")?"dog":value.Contains("tôm")?"shrimp":value.Contains("cá")?"fish":value.Contains("thỏ")?"rabbit":value.Contains("chim")?"bird":value.Contains("ong")?"bee":value.Contains("táo")?"apple":value.Contains("cam")?"orange":value.Contains("cà rốt")?"carrot":value.Contains("hoa")?"flower":value.Contains("bút")?"pencil":value.Contains("sách")?"book":value.Contains("cặp")?"backpack":value.Contains("cốc")?"bowl":value.Contains("xà phòng")||value.Contains("rửa tay")?"soap":value.Contains("bàn chải")||value.Contains("đánh răng")?"toothbrush":value.Contains("xin lỗi")?"folded-hands":value.Contains("cảm ơn")||value.Contains("nắm tay")?"handshake":value.Contains("dây an toàn")?"car":value.Contains("giày")?"shoe":value.Contains("áo mưa")?"coat":value.Contains("ô")?"umbrella":value.Contains("mũ")?"helmet":value.Contains("mặt trăng")||value.Contains("ban đêm")?"moon":value.Contains("mặt trời")||value.Contains("trời nắng")?"sun":value.Contains("trời mưa")||value.Contains("nước")?"water":value.Contains("cây")||value.Contains("hạt")?"seedling":value.Contains("bóng")?"ball":value.Contains("xe")?"car":"book";
        return $"/images/pictograms/{file}.svg";
    }
